raw:
{
  "spells": [
    {
      "id": "spell_wind_07",
      "theory": "风刃术把魔力压入一道薄而急的气流，使其贴着空气层滑出，像无形刀片划过。软布、绳索、薄皮容易被切开，但硬甲、厚盾或石墙会挡住气流，刃口随即散乱。施术者需理解气流的走向与目标表面的软硬，否则刃口会偏向一侧。",
      "casting": "五指并拢，从肩侧向目标方向斜挥，同时以短促吐气送出魔力，使气流在掌心外侧聚成薄片。挥动时手腕不可翻转。",
      "failure": "气流会在半途散成乱风，只吹动衣角或扬起尘土，不产生切口。若魔力送得太急，可能反冲回来割伤自己的袖口或手指。",
      "counters": [
        "举起厚盾或硬甲挡住气流，刃口会因表面过硬而偏斜。",
        "在目标前抛撒粗砂或灰土，颗粒会打乱薄气流的连续。"
      ],
      "socialConsequences": "河谷乡约允许在空地对草靶练习，但若割断邻家晾绳或伤及牲畜，须按实际损失赔偿。城中公会要求施术前确认周围没有行人，港口则关注是否割坏缆绳或帆布。皮匠和裁缝乐意用它裁切软料，但硬甲匠认为它威胁不到自己的生意，反而常提醒学徒别拿它试甲。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时气流方向常偏，只能切开薄布和细绳。",
        "熟练后能稳定切中近处软物，减少对周围的影响。",
        "掌握者能控制切口深浅，避免伤及目标下的物件。",
        "高熟练度使刃口更整齐，仍不能切开硬甲或石墙。"
      ]
    },
    {
      "id": "spell_wind_08",
      "theory": "静息幕将魔力铺成一层薄罩，吸收罩内空气的细碎震动，使风声和低语变得模糊。罩子不隔绝空气，也不阻挡实体，只让声音在边缘处散失。若罩内有人大声喊叫，仍能传出部分声响，但方向感会变差，远处听来像风吹过树叶。",
      "casting": "双手在胸前合拢再缓缓拉开，指尖相对，同时用平稳的鼻息送入魔力，使气息在两人之间形成半透明的罩痕。",
      "failure": "罩子会突然塌缩，风声短暂消失后反而更响，可能暴露位置。若魔力分布不均，罩内会出现一阵耳鸣般的低鸣，让附近的人感到不适。",
      "counters": [
        "在罩外敲击铜锣或吹响警号，高频声能穿透薄罩。",
        "用长竿挑动罩边空气，扰乱薄层使静音提前失效。"
      ],
      "socialConsequences": "河谷乡约允许在自家院落使用，但若用来掩盖呼救或警号，会被追究责任。中陆城市重视公会许可，商谈时使用静息幕常被视为保护隐私的礼貌。琥珀海岸港务提醒船主，在码头用此术掩盖号令可能延误避碰，若因此发生事故须承担货损赔偿。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学只能让罩内风声稍减，传话仍清晰可闻。",
        "熟练后低语变得模糊，但大声喊叫仍能传出。",
        "掌握者能维持罩子稳定，减少边缘漏音。",
        "高熟练度使静音范围更均匀，仍不能完全隔音。"
      ]
    },
    {
      "id": "spell_wind_09",
      "theory": "帆息调节在船帆表面铺一层魔力，修正帆面附近的局部气流，使帆布受力更均匀。它不能改变整片海风的方向或强度，只能让已有风在帆面上少打旋、少鼓包。施术者需理解帆的受风角度，否则修正会变成乱流，反而让船速不稳。",
      "casting": "一手按住桅杆，另一手沿帆边从下往上划弧，同时以细长吐气送入魔力，使帆面出现一层几乎看不见的波纹。",
      "failure": "帆面会突然抖动，发出拍打声，局部气流紊乱使船速忽快忽慢。若魔力送得太猛，可能扯松帆角绳索，需要水手立即收帆调整。",
      "counters": [
        "降下部分船帆减少受风面积，使局部修正失去作用。",
        "在帆索上系重物压住帆角，可抵消气流的不均匀拉扯。"
      ],
      "socialConsequences": "河谷船夫在熟悉水域使用它调整小帆，乡约只要求不撞坏渔网。中陆城市公会允许持证者在商船上施术，但若因乱流导致货物移位，须按货损赔偿。琥珀海岸港务规定，在港口航道内使用前须向港务报备，若干扰他船航行或造成碰撞，要追究责任并扣留相关货物。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常使帆面抖动，船速反而忽快忽慢。",
        "熟练后能均匀帆面受力，减少不必要的拍打。",
        "掌握者能配合舵手调整帆角，使航行更平稳。",
        "高熟练度让修正更细腻，仍不能改变整片海风。"
      ]
    }
  ]
}
